{"command":"cat << 'EOF' > logging.go
package main

import (
	"fmt"
	"os"
	"time"
)

var debugEnabled bool

func logMessage(level string, format string, a ...interface{}) {
	msg := fmt.Sprintf(format, a...)
	ts := time.Now().Format("2006-01-02 15:04:05")
	var formattedLevel string
	switch level {
	case "DEBUG":
		formattedLevel = "[DEBUG] "
	case "ERROR":
		formattedLevel = "[ERROR] "
	case "INFO":
		formattedLevel = "[INFO]  "
	case "WARN":
		formattedLevel = "[WARN]  "
	default:
		formattedLevel = fmt.Sprintf("[%s]", level)
	}
	fmt.Fprintf(os.Stderr, "%s %s%s\n", ts, formattedLevel, msg)
}

func logDebug(format string, a ...interface{}) {
	if debugEnabled {
		logMessage("DEBUG", format, a...)
	}
}

func logInfo(format string, a ...interface{}) {
	logMessage("INFO", format, a...)
}

func logWarn(format string, a ...interface{}) {
	logMessage("WARN", format, a...)
}

func logError(format string, a ...interface{}) {
	logMessage("ERROR", format, a...)
}

func exitProgram(code int, command string) {
	if debugEnabled {
		if code == 0 && command != "format" && command != "pull" {
			logDebug("Exit code 0 (SUCCESS)")
		} else {
			logDebug("Exit code %d", code)
		}
	}
	os.Exit(code)
}
EOF"}

