	"verify":                  true,
	"skip-verify":             true,
	"concurrent-servers":      true,
	"first-only":              true,
}

type SkeemaFile struct {
	FilePath string
	Globals  map[string]string
	Sections map[string]map[string]string
}

func parseSkeemaFile(filePath string) (*SkeemaFile, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	sf := &SkeemaFile{
		FilePath: filePath,
		Globals:  make(map[string]string),
		Sections: make(map[string]map[string]string),
	}

	scanner := bufio.NewScanner(file)
	currentSection := ""
	lineNum := 0

	for scanner.Scan() {
		lineNum++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}

		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			currentSection = strings.TrimSpace(line[1 : len(line)-1])
			if sf.Sections[currentSection] == nil {
				sf.Sections[currentSection] = make(map[string]string)
			}
			continue
		}

		var key, value string
		if idx := strings.IndexAny(line, "=:"); idx != -1 {
			key = strings.TrimSpace(line[:idx])
			value = strings.TrimSpace(line[idx+1:])
			if (strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\"")) ||
				(strings.HasPrefix(value, "'") && strings.HasSuffix(value, "'")) {
				if len(value) >= 2 {
					value = value[1 : len(value)-1]
				}
			}
		} else {
			key = line
			value = "1"
		}

		if !validConfigKeys[key] {
			return nil, fmt.Errorf("%s line %d: Unknown option \"%s\"", filePath, lineNum, key)
		}

		if currentSection == "" {
			sf.Globals[key] = value
		} else {
			sf.Sections[currentSection][key] = value
		}
	}

	return sf, nil
}

type Config struct {
	cliOptions map[string]string
}

func NewConfig(cliOpts map[string]string) *Config {
	return &Config{cliOptions: cliOpts}
}

func (c *Config) GetOptionForDir(dirPath string, env string, optName string) string {
	if val, ok := c.cliOptions[optName]; ok {
		return val
	}

	if optName == "password" {
		if envVal := os.Getenv("MYSQL_PWD"); envVal != "" {
			return envVal
		}
	}

	absDir, err := filepath.Abs(dirPath)
	if err != nil {
		absDir = dirPath
	}

	var dirs []string
	curr := absDir
	for {
		dirs = append([]string{curr}, dirs...)
		parent := filepath.Dir(curr)
		if parent == curr {
			break
		}
		curr = parent
	}

	for _, d := range dirs {
		skeemaPath := filepath.Join(d, ".skeema")
		if sf, err := parseSkeemaFile(skeemaPath); err == nil {
			if secMap, ok := sf.Sections[env]; ok {
				if val, ok := secMap[optName]; ok {
					return val
				}
			}
			if val, ok := sf.Globals[optName]; ok {
				return val
			}
		}
	}

	return getDefaultOptionValue(optName)
}

func getDefaultOptionValue(optName string) string {
	switch optName {
	case "port":
		return "3306"
	case "socket":
		return "/tmp/mysql.sock"
	case "user":
		return "root"
	case "workspace":
		return "temp-schema"
	case "temp-schema":
		return "_skeema_tmp"
	case "temp-schema-binlog":
		return "auto"
	case "temp-schema-mode":
		return "regular"
	case "temp-schema-threads":
		return "5"
	case "docker-cleanup":
		return "none"
	case "dir":
		return "."
	default:
		return ""
	}
}
EOF"}

