			return nil, fmt.Errorf("%s line %d: Unknown option \"%s\"", filePath, lineNum, key)
		}

		if currentSection == "" {
			sf.Globals[key] = value
		} else {
			sf.Sections[currentSection][key] = value
		}
	}

	return sf, nil
}

type Config struct {
	cliOptions map[string]string
}

func NewConfig(cliOpts map[string]string) *Config {
	return &Config{cliOptions: cliOpts}
}

func (c *Config) GetOptionForDir(dirPath string, env string, optName string) string {
	if val, ok := c.cliOptions[optName]; ok {
		return val
	}

	if optName == "password" {
		if envVal := os.Getenv("MYSQL_PWD"); envVal != "" {
			return envVal
		}
	}

	absDir, err := filepath.Abs(dirPath)
	if err != nil {
		absDir = dirPath
	}

	var dirs []string
	curr := absDir
	for {
		dirs = append([]string{curr}, dirs...)
		parent := filepath.Dir(curr)
		if parent == curr {
			break
		}
		curr = parent
	}

	for _, d := range dirs {
		skeemaPath := filepath.Join(d, ".skeema")
		if sf, err := parseSkeemaFile(skeemaPath); err == nil {
			if secMap, ok := sf.Sections[env]; ok {
				if val, ok := secMap[optName]; ok {
					return val
				}
			}
			if val, ok := sf.Globals[optName]; ok {
				return val
			}
		}
	}

	return getDefaultOptionValue(optName)
}

func getDefaultOptionValue(optName string) string {
	switch optName {
	case "port":
		return "3306"
	case "socket":
		return "/tmp/mysql.sock"
	case "user":
		return "root"
	case "workspace":
		return "temp-schema"
	case "temp-schema":
		return "_skeema_tmp"
	case "temp-schema-binlog":
		return "auto"
	case "temp-schema-mode":
		return "regular"
	case "temp-schema-threads":
		return "5"
	case "docker-cleanup":
		return "none"
	case "dir":
		return "."
	default:
		return ""
	}
}
EOF"}

