func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

type ParsedCLI struct {
	Command        string
	Options        map[string]string
	PositionalArgs []string
	HelpArg        string
	ShowHelp       bool
	ShowVersion    bool
}

func parseCLIArgs(args []string) (*ParsedCLI, error) {
	parsed := &ParsedCLI{
		Options: make(map[string]string),
	}

	var rawTokens []string
	var cmdName string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !strings.HasPrefix(arg, "-") && cmdName == "" {
			cmdName = arg
		} else {
			rawTokens = append(rawTokens, arg)
		}
	}

	if cmdName == "" {
		parsed.Command = ""
	} else {
		parsed.Command = cmdName
	}

	validMap := make(map[string]*OptionDef)
	for k, v := range commandValidOptions["global"] {
		validMap[k] = v
	}
	if cmdName != "" && commandValidOptions[cmdName] != nil {
		for k, v := range commandValidOptions[cmdName] {
			validMap[k] = v
		}
	}

	shortToDef := make(map[string]*OptionDef)
	for _, def := range validMap {
		if def.Short != "" {
			shortToDef[def.Short] = def
		}
	}

	var positional []string

	for i := 0; i < len(args); i++ {
		arg := args[i]

		if arg == "--version" {
			parsed.ShowVersion = true
			continue
		}

		if arg == "--help" || arg == "-?" {
			parsed.ShowHelp = true
			continue
		}

		if strings.HasPrefix(arg, "--help=") || strings.HasPrefix(arg, "-?") {
			parsed.ShowHelp = true
			if strings.HasPrefix(arg, "--help=") {
				parsed.HelpArg = strings.TrimPrefix(arg, "--help=")
			} else {
				parsed.HelpArg = strings.TrimPrefix(arg, "-?")
			}
			continue
		}

		if strings.HasPrefix(arg, "--") {
			optPart := strings.TrimPrefix(arg, "--")
			var key, val string
			hasEq := false
			if idx := strings.Index(optPart, "="); idx != -1 {
				key = optPart[:idx]
				val = optPart[idx+1:]
				hasEq = true
			} else {
				key = optPart
			}

			isSkip := false
			lookupKey := key
			if strings.HasPrefix(key, "skip-") {
				isSkip = true
			}

			def, ok := validMap[lookupKey]
			if !ok {
				errKey := key
				if isSkip {
					errKey = strings.TrimPrefix(key, "skip-")
				}
				logError("CLI: Unknown option \"%s\"", errKey)
				return nil, fmt.Errorf("UNKNOWN_OPTION")
			}

			if def.Name == "my-cnf" {
				logWarn("Option --my-cnf is deprecated. This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes")
			}

			if def.Name == "temp-schema-threads" {
				logWarn("Option --temp-schema-threads is deprecated. This option will be removed in Skeema v2. Use the new temp-schema-mode enum option instead. See --help or visit https://www.skeema.io/docs/options/#temp-schema-mode")
			}

			if def.IsBool {
				if isSkip {
					parsed.Options[def.Name] = "0"
				} else {
					parsed.Options[def.Name] = "1"
				}
			} else if def.OptVal {
				if hasEq {
					parsed.Options[def.Name] = val
				} else {
					if def.Name == "password" {
						if !isTerminal(os.Stdin.Fd()) {
							fmt.Println("Enter password: ")
							logError("STDIN must be a TTY to read password")
							logError("Interactive password prompting requires an input terminal. To supply a password non-interactively, configure the password value in a global option file, or supply it directly on the command-line, or set the $MYSQL_PWD environment variable. For more information, see https://www.skeema.io/docs/options/#password")
							return nil, fmt.Errorf("TTY_ERROR")
						}
					}
					parsed.Options[def.Name] = ""
				}
			} else {
				if hasEq {
					parsed.Options[def.Name] = val
				} else {
					if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
						parsed.Options[def.Name] = args[i+1]
						i++
					} else {
						logError("CLI: Missing required value for option %s", key)
						return nil, fmt.Errorf("MISSING_VAL")
					}
				}
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			shortChar := string(arg[1])
			def, ok := shortToDef[shortChar]
			if !ok {
				logError("CLI: Unknown option \"%s\"", shortChar)
				return nil, fmt.Errorf("UNKNOWN_OPTION")
			}

			if def.Name == "password" {
				if len(arg) > 2 {
					parsed.Options[def.Name] = arg[2:]
				} else {
					if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
						parsed.Options[def.Name] = args[i+1]
						i++
					} else {
						if !isTerminal(os.Stdin.Fd()) {
							fmt.Println("Enter password: ")
							logError("STDIN must be a TTY to read password")
							logError("Interactive password prompting requires an input terminal. To supply a password non-interactively, configure the password value in a global option file, or supply it directly on the command-line, or set the $MYSQL_PWD environment variable. For more information, see https://www.skeema.io/docs/options/#password")
							return nil, fmt.Errorf("TTY_ERROR")
						}
					}
				}
			} else if def.IsBool {
				parsed.Options[def.Name] = "1"
			} else {
				if len(arg) > 2 {
					parsed.Options[def.Name] = arg[2:]
				} else {
					if i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
						parsed.Options[def.Name] = args[i+1]
						i++
					} else {
						logError("CLI: Missing required value for option %s", def.Name)
						return nil, fmt.Errorf("MISSING_VAL")
					}
				}
			}
		} else {
			positional = append(positional, arg)
		}
	}

	if len(positional) > 0 {
		if parsed.Command == "" {
			parsed.Command = positional[0]
			parsed.PositionalArgs = positional[1:]
		} else {
			var rem []string
			for _, p := range positional {
				if p != parsed.Command {
					rem = append(rem, p)
				}
			}
			parsed.PositionalArgs = rem
		}
	}

	if parsed.Options["debug"] == "1" {
		debugEnabled = true
	}

	return parsed, nil
}
EOF"}

