)

func handleFormat(cfg *Config, parsed *ParsedCLI) {
	if len(parsed.PositionalArgs) > 1 {
		logError("Extra command-line arg \"%s\" supplied; command format takes a max of 1 args", parsed.PositionalArgs[1])
		exitProgram(78, "format")
	}

	envName := "production"
	if len(parsed.PositionalArgs) == 1 {
		envName = parsed.PositionalArgs[0]
	}

	cwd, _ := os.Getwd()
	absCwd, _ := filepath.Abs(cwd)

	var dirsWithSql []string
	filepath.Walk(absCwd, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			if strings.HasPrefix(info.Name(), ".") && path != absCwd {
				return filepath.SkipDir
			}
			entries, _ := os.ReadDir(path)
			for _, entry := range entries {
				if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".sql") {
					dirsWithSql = append(dirsWithSql, path)
					break
				}
			}
		}
		return nil
	})

	if len(dirsWithSql) == 0 {
		logInfo("Reformatting %s", absCwd)
		exitProgram(0, "format")
	}

	for _, dirPath := range dirsWithSql {
		logInfo("Reformatting %s", dirPath)

		workspace := cfg.GetOptionForDir(dirPath, envName, "workspace")
		host := cfg.GetOptionForDir(dirPath, envName, "host")
		flavor := cfg.GetOptionForDir(dirPath, envName, "flavor")

		if workspace == "temp-schema" {
			if host == "" {
				logError("Skipping %s: This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment \"%s\"", dirPath, envName)
				exitProgram(78, "format")
			} else {
				port := cfg.GetOptionForDir(dirPath, envName, "port")
				socket := cfg.GetOptionForDir(dirPath, envName, "socket")
				var connErr error
				var connStr string
				if host == "localhost" {
					connStr = "localhost:" + socket
					_, connErr = net.Dial("unix", socket)
				} else {
					connStr = host + ":" + port
					_, connErr = net.Dial("tcp", connStr)
				}
				logError("Skipping %s: Unable to connect to %s for %s: %s", dirPath, connStr, dirPath, connErr)
				exitProgram(78, "format")
			}
		} else if workspace == "docker" {
			if flavor == "" {
				logError("Skipping %s: This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment \"%s\"", dirPath, envName)
				exitProgram(78, "format")
			} else {
				logError("Skipping %s: unable to find `docker` command-line client among directories in PATH", dirPath)
				exitProgram(2, "format")
			}
		}
	}

	exitProgram(0, "format")
}
