cat << 'EOF' > cmd_lint.go
package main

import (
	"net"
	"os"
	"path/filepath"
	"strings"
)

func handleLint(cfg *Config, parsed *ParsedCLI) {
	if len(parsed.PositionalArgs) > 1 {
		logError("Extra command-line arg \"%s\" supplied; command lint takes a max of 1 args", parsed.PositionalArgs[1])
		exitProgram(78, "lint")
	}

	envName := "production"
	if len(parsed.PositionalArgs) == 1 {
		envName = parsed.PositionalArgs[0]
	}

	if debugEnabled {
		logDebug("Upgrade notice: the --format option, which currently defaults to true in Skeema v1, will change to default to false in Skeema v2. For more information, visit https://www.skeema.io/v2-changes")
	}

	cwd, _ := os.Getwd()
	absCwd, _ := filepath.Abs(cwd)

	var dirsToLint []string
	filepath.Walk(absCwd, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			if strings.HasPrefix(info.Name(), ".") && path != absCwd {
				return filepath.SkipDir
			}
			dirsToLint = append(dirsToLint, path)
		}
		return nil
	})

	skippedCount := 0
	dockerError := false

	baseName := filepath.Base(absCwd)

	for _, dirPath := range dirsToLint {
		relDirName := baseName
		if dirPath != absCwd {
			rel, _ := filepath.Rel(absCwd, dirPath)
			relDirName = baseName + "/" + rel
		}

		logInfo("Linting %s", dirPath)

		entries, _ := os.ReadDir(dirPath)
		hasSql := false
		for _, entry := range entries {
			if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".sql") {
				hasSql = true
				break
			}
		}

		hasSchemaInSkeema := false
		skeemaPath := filepath.Join(dirPath, ".skeema")
		if sf, err := parseSkeemaFile(skeemaPath); err == nil {
			if secMap, ok := sf.Sections[envName]; ok {
				if _, ok := secMap["schema"]; ok {
					hasSchemaInSkeema = true
				}
			}
			if _, ok := sf.Globals["schema"]; ok {
				hasSchemaInSkeema = true
			}
		}

		if hasSql || hasSchemaInSkeema {
			workspace := cfg.GetOptionForDir(dirPath, envName, "workspace")
			host := cfg.GetOptionForDir(dirPath, envName, "host")
			flavor := cfg.GetOptionForDir(dirPath, envName, "flavor")

			if workspace == "temp-schema" {
				if host == "" {
					logError("Skipping directory %s due to error: This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment \"%s\"", relDirName, envName)
					skippedCount++
				} else {
					port := cfg.GetOptionForDir(dirPath, envName, "port")
					socket := cfg.GetOptionForDir(dirPath, envName, "socket")
					var connErr error
					var connStr string
					if host == "localhost" {
						connStr = "localhost:" + socket
						_, connErr = net.Dial("unix", socket)
					} else {
						connStr = host + ":" + port
						_, connErr = net.Dial("tcp", connStr)
					}
					logError("Skipping directory %s due to error: Unable to connect to %s for %s: %s", relDirName, connStr, dirPath, connErr)
					skippedCount++
				}
			} else if workspace == "docker" {
				if flavor == "" {
					logError("Skipping directory %s due to error: This command needs either a host (with workspace=temp-schema) or flavor (with workspace=docker), but one is not configured for environment \"%s\"", relDirName, envName)
					skippedCount++
				} else {
					if debugEnabled {
						logDebug("Upgrade notice: the --docker-cleanup option, which currently defaults to \"none\" in Skeema v1, will change to default to \"stop\" in Skeema v2. For more information, visit https://www.skeema.io/v2-changes")
					}
					logError("Skipping directory %s due to error: unable to find `docker` command-line client among directories in PATH", relDirName)
					logError("Skeema v1.11+ no longer includes a built-in Docker client. If you are using workspace=docker while also running `skeema` itself in a container, be sure to put a Linux `docker` client CLI binary in the container as well.")
					logError("For more information, see https://github.com/skeema/skeema/issues/186#issuecomment-1648483625")
					skippedCount++
					dockerError = true
				}
			}
		}
	}

	if skippedCount > 0 {
		if skippedCount == 1 {
			logError("Skipped 1 operation due to fatal errors")
		} else {
			logError("Skipped %d operations due to fatal errors", skippedCount)
		}
		if dockerError {
			exitProgram(2, "lint")
		} else {
			exitProgram(78, "lint")
		}
	}

	exitProgram(0, "lint")
}
