package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func handleAddEnvironment(cfg *Config, parsed *ParsedCLI) {
	if len(parsed.PositionalArgs) == 0 {
		logError("Too few positional args supplied on command line; command add-environment requires at least 1 args")
		exitProgram(78, "add-environment")
	}
	if len(parsed.PositionalArgs) > 1 {
		logError("Extra command-line arg \"%s\" supplied; command add-environment takes a max of 1 args", parsed.PositionalArgs[1])
		exitProgram(78, "add-environment")
	}

	envName := parsed.PositionalArgs[0]
	dirOpt := cfg.GetOptionForDir(".", envName, "dir")
	if dirOpt == "" {
		dirOpt = "."
	}

	absDir, err := filepath.Abs(dirOpt)
	if err != nil {
		absDir = dirOpt
	}

	fi, err := os.Stat(absDir)
	if err != nil || !fi.IsDir() {
		logError("In add-environment, --dir must refer to a directory that already exists")
		exitProgram(78, "add-environment")
	}

	skeemaFile := filepath.Join(absDir, ".skeema")
	sf, err := parseSkeemaFile(skeemaFile)
	if err != nil {
		if strings.Contains(err.Error(), "Unknown option") {
			logError("%s", err.Error())
			exitProgram(78, "add-environment")
		}
		logError("Dir %s does not have an existing .skeema file! Can only use `skeema add-environment` on a dir previously created by `skeema init`", absDir)
		exitProgram(78, "add-environment")
	}

	hasHostInAnySection := false
	if _, ok := sf.Globals["host"]; ok {
		hasHostInAnySection = true
	} else {
		for _, secMap := range sf.Sections {
			if _, ok := secMap["host"]; ok {
				hasHostInAnySection = true
				break
			}
		}
	}

	if !hasHostInAnySection {
		logError("This command should be run against a --dir whose .skeema file already defines a host for another environment")
		exitProgram(78, "add-environment")
	}

	cliHost, hostInCLI := parsed.Options["host"]
	if !hostInCLI || cliHost == "" {
		logError("`skeema add-environment` requires --host to be supplied on command-line")
		exitProgram(78, "add-environment")
	}

	if _, ok := sf.Sections[envName]; ok {
		logError("Environment name \"%s\" already defined in %s", envName, skeemaFile)
		exitProgram(78, "add-environment")
	}

	portVal := parsed.Options["port"]
	if portVal == "" {
		portVal = "3306"
	}
	socketVal := parsed.Options["socket"]
	if socketVal == "" {
		socketVal = "/tmp/mysql.sock"
	}

	f, err := os.OpenFile(skeemaFile, os.O_APPEND|os.O_WRONLY, 0644)
	if err != nil {
		logError("Unable to open %s: %s", skeemaFile, err)
		exitProgram(78, "add-environment")
	}
	defer f.Close()

	var lines []string
	lines = append(lines, "")
	lines = append(lines, fmt.Sprintf("[%s]", envName))
	lines = append(lines, fmt.Sprintf("host=%s", cliHost))

	if cliHost == "localhost" {
		if portInCLI, ok := parsed.Options["port"]; ok && portInCLI != "3306" {
			lines = append(lines, fmt.Sprintf("port=%s", portInCLI))
		} else {
			lines = append(lines, fmt.Sprintf("socket=%s", socketVal))
		}
	} else {
		lines = append(lines, fmt.Sprintf("port=%s", portVal))
	}

	_, err = f.WriteString(strings.Join(lines, "\n") + "\n")
	if err != nil {
		logError("Unable to write to %s: %s", skeemaFile, err)
		exitProgram(78, "add-environment")
	}

	logWarn("Unable to automatically determine database server's vendor/version. To set manually, use the \"flavor\" option in %s", skeemaFile)
	logInfo("Added environment [%s] to %s", envName, skeemaFile)
	exitProgram(0, "add-environment")
}

