		fmt.Print(helpTexts["main"])
		os.Exit(0)
	}

	parsed, err := parseCLIArgs(args)
	if err != nil {
		if err.Error() == "TTY_ERROR" || err.Error() == "UNKNOWN_OPTION" || err.Error() == "MISSING_VAL" {
