		if parsed.HelpArg != "" {
			handleHelp(parsed.HelpArg, nil)
		} else if parsed.Command != "" && parsed.Command != "help" {
			handleHelp(parsed.Command, nil)
		} else {
			handleHelp("", parsed.PositionalArgs)
		}
		return
	}

	cfg := NewConfig(parsed.Options)

	switch parsed.Command {
	case "version":
		handleVersion(parsed)
	case "help":
		handleHelp("", parsed.PositionalArgs)
