{"command":"cat << 'EOF' > cmd_init.go
package main

import (
	"net"
	"os"
	"path/filepath"
)

func handleInit(cfg *Config, parsed *ParsedCLI) {
	if len(parsed.PositionalArgs) > 1 {
		logError("Extra command-line arg \"%s\" supplied; command init takes a max of 1 args", parsed.PositionalArgs[1])
		exitProgram(78, "init")
	}

	envName := "production"
	if len(parsed.PositionalArgs) == 1 {
		envName = parsed.PositionalArgs[0]
	}

	dirOpt := cfg.GetOptionForDir(".", envName, "dir")
	if dirOpt == "" {
		dirOpt = "."
	}

	absDir, err := filepath.Abs(dirOpt)
	if err != nil {
		absDir = dirOpt
	}

	cliHost, hostInCLI := parsed.Options["host"]
	if !hostInCLI || cliHost == "" {
		logError("Option --host must be supplied on the command-line")
		exitProgram(78, "init")
	}

	skeemaFile := filepath.Join(absDir, ".skeema")
	if _, err := os.Stat(skeemaFile); err == nil {
		logError("Cannot use dir %s: already has .skeema file", absDir)
		exitProgram(78, "init")
	}

	portVal := cfg.GetOptionForDir(absDir, envName, "port")
	socketVal := cfg.GetOptionForDir(absDir, envName, "socket")

	var connErr error
	var connStr string
	if cliHost == "localhost" {
		connStr = "localhost:" + socketVal
		_, connErr = net.Dial("unix", socketVal)
	} else {
		connStr = cliHost + ":" + portVal
		_, connErr = net.Dial("tcp", connStr)
	}

	if connErr != nil {
		logError("Unable to connect to %s for %s: %s", connStr, absDir, connErr)
		exitProgram(2, "init")
	}

	exitProgram(0, "init")
}
EOF"}

